            aOrbiterK = (((aOrbiterK ^ aOrbiterD) ^ 0x570FBC4EF7480914ULL) ^ aPhaseDOrbiterUpdateSaltF[((aIndex + 3U)) & S_SALT1]) ^ aNonceWordE;
