            aOrbiterC = ((aOrbiterC + aOrbiterG) + 0x4E327A5B7F14779DULL) + aNonceWordJ;
            aOrbiterE = (aOrbiterE ^ aOrbiterC) ^ 0xAB2456A191BBD64DULL;
