            aCross = (RotL64(aWaterLaneB[((S_BLOCK1 - aIndex + 30206U)) & S_BLOCK1], 27U) ^ RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 31990U)) & S_BLOCK1], 3U));
