            //
            aOrbiterI = (aWandererB + RotL64(aIngress, 29U)) + 0x1CD9992A2291C0C4ULL;
            aOrbiterK = (((aWandererK + RotL64(aCross, 56U)) + 0xC78218D4CA1E7B08ULL) + aPhaseBOrbiterAssignSaltC[((aIndex + 13U)) & S_SALT1]) + aNonceWordP;
            aOrbiterF = (aWandererJ + RotL64(aScatter, 53U)) + 0x56EACC4769DDB1CDULL;
            aOrbiterG = ((aWandererI + RotL64(aPrevious, 39U)) + RotL64(aCarry, 23U)) + 0x3F7F7207372DB579ULL;
            aOrbiterC = (aWandererA + RotL64(aIngress, 5U)) + 0x7236497E6C0E82ECULL;
            aOrbiterB = ((aWandererD + RotL64(aPrevious, 3U)) + 0x6737D6D5C6574B2FULL) + aPhaseBOrbiterAssignSaltE[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterE = (aWandererF + RotL64(aCross, 13U)) + 0xAC3B746FB4C921CCULL;
            aOrbiterJ = (aWandererH + RotL64(aScatter, 10U)) + 0x8D9F4A77DAD269A4ULL;
            aOrbiterA = (aWandererG + RotL64(aPrevious, 23U)) + 0x9B975309CDE7DCE1ULL;
            aOrbiterH = (((aWandererE + RotL64(aIngress, 27U)) + RotL64(aCarry, 19U)) + 0xB315125283D35523ULL) + aNonceWordE;
