            aOrbiterK = (((aOrbiterK + aOrbiterG) + 0x3A5FBF55C9D7B86FULL) + aPhaseBOrbiterUpdateSaltE[((aIndex + 16U)) & S_SALT1]) + aNonceWordH;
            aOrbiterC = ((aOrbiterC ^ aOrbiterK) ^ 0xE9012ACDD1196585ULL) ^ aPhaseBOrbiterUpdateSaltB[(((31U - aIndex) + 24U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x098B2B0A380F3399ULL), 41U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterE) + 0xC91731AD3311E99AULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterB) ^ 0x066B98CE1DD98246ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x8CD1CAF5F1CCA42BULL), 19U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterJ) + 0xAEC8A8409BD3534BULL) + aNonceWordO;
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0xEDC40566A12B67F6ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x795397159B0DC9DFULL), 37U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterF) + 0x11058F7F5D3BB896ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterG) ^ 0xDA31969FAC04AC67ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xCDCB745B21C4162DULL), 51U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterC) + 0x193F44CB86D4504FULL;
