            //
            aOrbiterD = ((aOrbiterD + aOrbiterB) + 0x81CCC0EE3F430397ULL) + aPhaseBOrbiterUpdateSaltD[(((31U - aIndex) + 4U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterD) ^ 0xCADB14246F98DA93ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xDDC6F8BD816B2163ULL), 39U);
