            //
            aOrbiterB = (((aWandererH + RotL64(aCross, 60U)) + RotL64(aCarry, 35U)) + 0xF58425F59C5BF479ULL) + aPhaseAOrbiterAssignSaltB[((aIndex + 20U)) & S_SALT1];
