            aOrbiterA = (aWandererH + RotL64(aPrevious, 13U)) + 0xF58DF154BF7D47DCULL;
            aOrbiterD = ((aWandererB + RotL64(aIngress, 39U)) + 0x56AD880A1C7068F0ULL) + aPhaseAOrbiterAssignSaltC[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterH = ((aWandererC + RotL64(aCross, 57U)) + RotL64(aCarry, 27U)) + 0x88342B3816BAE075ULL;
            aOrbiterI = ((aWandererD + RotL64(aPrevious, 5U)) + RotL64(aCarry, 53U)) + 0x1341C07579996C52ULL;
            aOrbiterB = (aWandererI + RotL64(aScatter, 27U)) + 0x0AA9AF0D7103844FULL;
            //
            aOrbiterC = ((aOrbiterC + aOrbiterE) + 0x56C69EA712681EA0ULL) + aPhaseAOrbiterUpdateSaltA[((aIndex + 26U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterC) ^ 0xF2D2671575551EA1ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x40615E37F168665DULL), 11U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterH) + 0x2F766EACAF827372ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0x496259FD2C480D26ULL;
