            aOrbiterH = (aOrbiterH + aOrbiterI) + 0x2DD6551DB08FBB72ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterH) ^ 0x5E506F5FBC4C46AAULL;
            aOrbiterE = RotL64((aOrbiterE * 0x4D878A60DE36AF97ULL), 21U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterC) + 0x04EAFB32313E3BCDULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterI) ^ 0x539EB47A9A08DD0FULL;
            aOrbiterB = RotL64((aOrbiterB * 0x1A0F1E3AE1E4A799ULL), 47U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterB) + 0x7531DCD197B72FDBULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterE) ^ 0x41226C772177DD7EULL;
