            aWandererB = aWandererB + (((RotL64(aPrevious, 12U) + RotL64(aOrbiterB, 38U)) + aOrbiterD) + RotL64(aCarry, 57U));
            aWandererK = aWandererK ^ ((RotL64(aScatter, 21U) + RotL64(aOrbiterD, 51U)) + aOrbiterE);
            aWandererD = aWandererD + (((RotL64(aIngress, 5U) + RotL64(aOrbiterI, 3U)) + aOrbiterC) + aPhaseAWandererUpdateSaltF[(((31U - aIndex) + 19U)) & S_SALT1]);
            aWandererC = aWandererC ^ (((RotL64(aCross, 41U) + RotL64(aOrbiterH, 57U)) + aOrbiterE) + aPhaseAWandererUpdateSaltC[((aIndex + 23U)) & S_SALT1]);
